def choose_move(observation):
    def sgn(v):
        return 0 if v == 0 else (1 if v > 0 else -1)

    def pos(v):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return v[0], v[1]
        return None

    def dist(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def move_toward(a, b):
        return [sgn(b[0] - a[0]), sgn(b[1] - a[1])]

    def move_away(a, b):
        return [sgn(a[0] - b[0]), sgn(a[1] - b[1])]

    env = observation.get("environment_name", "resource_collection")
    self_pos = pos(observation.get("self_position")) or (0, 0)
    opp_pos = pos(observation.get("opponent_position"))
    gw = observation.get("grid_width", 0) or 0
    gh = observation.get("grid_height", 0) or 0

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            if opp_pos is not None:
                return move_toward(self_pos, opp_pos)
            targets = observation.get("targets") or observation.get("resources") or []
            best = None
            best_d = None
            for t in targets:
                p = pos(t)
                if p is None:
                    continue
                d = dist(self_pos, p)
                if best is None or d < best_d:
                    best, best_d = p, d
            return move_toward(self_pos, best) if best is not None else [0, 0]
        if opp_pos is not None:
            corners = [(0, 0), (0, max(0, gh - 1)), (max(0, gw - 1), 0), (max(0, gw - 1), max(0, gh - 1))]
            target = None
            best_d = None
            for c in corners:
                d = dist(opp_pos, c)
                if target is None or d > best_d:
                    target, best_d = c, d
            return move_toward(self_pos, target)
        return [0, 0]

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("frontier") or []
        best = None
        best_d = None
        for t in targets:
            p = pos(t)
            if p is None:
                continue
            d = dist(self_pos, p)
            if best is None or d < best_d:
                best, best_d = p, d
        if best is not None:
            return move_toward(self_pos, best)
        center = (max(0, gw // 2), max(0, gh // 2))
        if opp_pos is not None and dist(self_pos, opp_pos) <= 2:
            return move_away(self_pos, opp_pos)
        return move_toward(self_pos, center)

    resources = observation.get("resources") or observation.get("resource_cells") or []
    best = None
    best_d = None
    for r in resources:
        p = pos(r)
        if p is None:
            continue
        d = dist(self_pos, p)
